["Window"] = "창",
["Window 1 stays; the others can go."] = "창 1은 유지되고 나머지는 제거할 수 있습니다.",
["Window height"] = "창 높이",
["Window look"] = "창 모양",
["Window width"] = "창 너비",
["Windows"] = "창",
["Windows snap together"] = "창이 서로 붙음",
["With ClassicAPI the whole set goes on at once, without the cursor; off = one item at a time, as without it."] = "ClassicAPI가 있으면 커서 없이 세트 전체가 한 번에 착용됩니다. 끄면 없을 때처럼 하나씩 착용합니다.",
["With ClassicAPI."] = "ClassicAPI 사용 시.",
["With aggro: the next player"] = "어그로가 있을 때: 다음 플레이어",
["With commas (12,345)"] = "쉼표 사용 (12,345)",
