["Wobble Zoom"] = "흔들며 확대",
["Word (Elite, Rare, Boss)"] = "단어 (정예, 희귀, 우두머리)",
["Word colour"] = "단어 색상",
["Words"] = "단어",
["Words to highlight, like: Onyxia, summon, guild bank (at least 3 letters each)."] = "강조할 단어, 예: 오닉시아, 소환, 길드 은행 (각각 3글자 이상).",
["Words, like: gold, cheap, www (lines from players only)."] = "단어, 예: gold, cheap, www (플레이어가 보낸 줄만).",
["Words: Threat 72%"] = "글자: 위협 72%",
["Wow Skill"] = "Wow Skill",
["Wow Status"] = "Wow Status",
